/*
 * Contact metadata is kept separate from PLACES_RAW for backward compatibility.
 * Add only verified phone numbers or official websites to LOCATION_CONTACTS.
 * Every place receives a Google Maps search URL built from its name and coordinates.
 */
window.LOCATION_CONTACTS = {
  // Example:
  // "โรงแรมเฟื่องฟ้ารีสอร์ท": {
  //   phone: "+6675xxxxxx",
  //   website: "https://official-hotel.example",
  //   source: "official",
  //   verifiedAt: "2026-10-20"
  // }
};

window.getLocationContact = function(name) {
  var item = window.LOCATION_CONTACTS[String(name || '').trim()];
  return item && typeof item === 'object' ? item : {};
};

window.buildGoogleMapsSearchUrl = function(name, lat, lng) {
  var query = String(name || '').trim();
  if (isFinite(Number(lat)) && isFinite(Number(lng))) {
    query += (query ? ', ' : '') + Number(lat) + ',' + Number(lng);
  }
  return 'https://www.google.com/maps/search/?api=1&query=' + encodeURIComponent(query || 'ชะอวด นครศรีธรรมราช');
};

window.LOCATION_METADATA_BY_ID = window.PLACES_RAW.reduce(function(out, item, index) {
  var contact = window.getLocationContact(item[0]);
  var id = 'LOC-' + String(index + 1).padStart(3, '0');
  out[id] = {
    phone: String(contact.phone || item[7] || '').trim(),
    website: String(contact.website || item[8] || '').trim(),
    mapsUrl: String(contact.mapsUrl || item[9] || window.buildGoogleMapsSearchUrl(item[0], item[1], item[2])),
    source: contact.source || (contact.phone ? 'verified-contact' : 'Google Maps search'),
    verifiedAt: contact.verifiedAt || ''
  };
  return out;
}, {});
